// Cut the document into overlapping windows of WORDS.
//
// 180 words with 30 of overlap - the same numbers the rehearsal script used against
// the real stack, so what you get here matches what you see there: the four practice
// documents are each shorter than 180 words, so each becomes exactly one chunk.
//
// Words, not characters. A character cut lands mid-word and mid-number; "$7,700"
// becomes "$7," in one chunk and "700" in the next, and neither matches a question
// about the deposit. Words cannot split a figure in half.
//
// The overlap is not decoration: a sentence that straddles a boundary would
// otherwise be split across two chunks and match neither of them well.
const CHUNK_WORDS = 180;
const OVERLAP_WORDS = 30;

const out = [];

for (const item of $input.all()) {
  const text = (item.json.data || item.json.content || '').toString();

  // The filename, not the full path - this is what gets shown as the citation.
  // Read File leaves it on the binary rather than the json, so check both.
  const full = item.json.fileName || item.json.filePath ||
               (item.binary && item.binary.data && item.binary.data.fileName);

  // Deliberately no fallback name. Give several documents the same source and they
  // all collapse onto one row through UNIQUE (source, chunk_index) - four documents
  // in, one row out, every node green. A citation you cannot trace is worth stopping
  // for.
  if (!full) {
    throw new Error(
      'No filename on this item, so there is nothing to cite. Read File puts it on ' +
      'the binary as $binary.data.fileName - if you are feeding this node from ' +
      'somewhere else, set fileName on the item first.'
    );
  }

  const source = full.split('/').pop().split('\\').pop();

  if (!text.trim()) {
    throw new Error(`${source} read as empty. Can the n8n container see the file?`);
  }

  const words = text.split(/\s+/).filter(Boolean);
  const step = CHUNK_WORDS - OVERLAP_WORDS;

  let idx = 0;
  for (let i = 0; i < words.length; i += step) {
    const window = words.slice(i, i + CHUNK_WORDS);
    if (!window.length) continue;
    out.push({ json: {
      source,
      chunk_index: idx++,
      content: window.join(' ')
    }});

    // Stop the moment a window reaches the end. Without this, a document
    // shorter than two steps emits a last chunk that is already contained in
    // the one before it - a scrap that costs an embedding call and can take one
    // of the five slots retrieved for a question. Every practice document in
    // the pack is short enough to hit it.
    if (i + CHUNK_WORDS >= words.length) break;
  }
}

return out;

// Pull the vector out and prove it is the right size BEFORE we try to insert it.
//
// The kb table has a CHECK constraint on 1536 dimensions. Without this node a bad
// embedding still fails - but it fails in Postgres, and the error points at the
// database instead of at the model that actually caused it.
const emb = $json.data?.[0]?.embedding;

if (!Array.isArray(emb)) {
  throw new Error(
    'No embedding in the response. Check the OpenRouter credential and that the ' +
    'key has a balance - an unfunded key does not say so in plain language.'
  );
}
if (emb.length !== 1536) {
  throw new Error(
    `Embedding came back with ${emb.length} dimensions, expected 1536. ` +
    'A different model returns a different size, and mixing sizes silently ' +
    'ruins every search in the table.'
  );
}

// Carry the chunk fields through from the chunker.
const src = $('Chunk it').all()[$itemIndex].json;

return { json: { ...src, embedding: emb } };
